import math
for _ in range(int(input())):
	(k, arr) = (int(input()), sorted(list(map(int, input().split()))))
	if k % 2 == 0:
		print(0)
	else:
		(m, M) = (-1, [])
		for i in range(k):
			if arr[i] % 2 == 0:
				m = 1
				break
		if m == -1:
			for i in range(k):
				if (arr[i] - 1) // 2 % 2 == 0 and arr[i] > 2:
					m = 2
					break
		if m == -1:
			for i in range(k):
				if math.log(arr[i] + 1, 2) != int(math.log(arr[i] + 1, 2)) and arr[i] > 2:
					b = list(bin(arr[i])[2:])
					if '0' in b:
						M.append(pow(2, b[::-1].index('0')))
		print(m) if M == [] else print(min(M))
